    bottom = [c for c, v in enumerate(grid[-1]) if v != bg]
    left = [r for r in range(h) if grid[r][0] != bg]
    right = [r for r in range(h) if grid[r][-1] != bg]

    dots = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] != bg and r not in (0, h-1) and c not in (0, w-1)]
    if top or bottom:
        lanes = sorted(set(top + bottom))
        for r, c, color in dots:
            lane = min(lanes, key=lambda x: abs(x-c))
            for rr in range(h):
                if grid[rr][lane] == bg:
                    out[rr][lane] = color
            out[r][c] = 4
