    edge = []
    for c in range(w):
        if grid[0][c] != bg:
            edge.append(("h", 0, c, grid[0][c]))
        if grid[h-1][c] != bg:
            edge.append(("h", h-1, c, grid[h-1][c]))
    for r in range(h):
