    for c, v in enumerate(grid[-1]):
        if v != bg:
            bars.append(("bottom", c, v))
    for r in range(h):
        if grid[r][0] != bg:
            bars.append(("left", r, grid[r][0]))
        if grid[r][-1] != bg:
            bars.append(("right", r, grid[r][-1]))

