        for c in range(w):
            color = grid[r][c]
            if color == bg or r in (0, h-1) or c in (0, w-1):
                continue
            choices = []
            for side, pos, _ in bars:
                if side in ("top", "bottom"):
                    choices.append((abs(c-pos), side))
                else:
                    choices.append((abs(r-pos), side))
            if not choices:
                continue
            _, side = min(choices)
            out[r][c] = 4
            if side in ("top", "bottom"):
                step = -1 if side == "top" else 1
                rr = r + step
                while 0 <= rr < h and grid[rr][c] == bg:
                    out[rr][c] = color
                    rr += step
            else:
                step = -1 if side == "left" else 1
                cc = c + step
                while 0 <= cc < w and grid[r][cc] == bg:
                    out[r][cc] = color
                    cc += step
    return out
